import React from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { onAuthStateChanged } from "firebase/auth";
import { doc, getDoc } from "firebase/firestore";

import Home from "./Home";
import SignIn from "./SignIn";
import Register from "./Register";
import Admin from "./adminBlock";
import ConsumerDashboard from "./ConsumerDashboard";
import FarmerDashboard from "./FarmerDashboard";
import Prices from "./Prices";
import Profile from "./Profile";

import { auth, db } from "./firebaseConfig";
import { isAdmin } from "./admin";

function ProtectedRoute({ children }) {
  const [user, setUser] = React.useState(auth.currentUser);
  const [checking, setChecking] = React.useState(true);

  React.useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setChecking(false);
    });

    return () => unsubscribe();
  }, []);

  if (checking) {
    return <p>Checking account...</p>;
  }

  if (!user) {
    return <Navigate to="/signin" replace />;
  }

  return children;
}

function FarmerRoute({ children }) {
  const [user, setUser] = React.useState(auth.currentUser);
  const [allowed, setAllowed] = React.useState(null);

  React.useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);

      if (!currentUser) {
        setAllowed(false);
        return;
      }

      const snapshot = await getDoc(doc(db, "users", currentUser.uid));
      const userData = snapshot.exists() ? snapshot.data() : {};
      const admin = await isAdmin(currentUser.uid);
      const isApprovedFarmer =
        userData.userType === "farmer" &&
        (userData.approved === true ||
          userData.status === "approved" ||
          userData.status === "verified" ||
          userData.accountStatus?.registrationStatus === "verified" ||
          userData.accountStatus?.documentStatus === "approved");

      setAllowed(admin || isApprovedFarmer);
    });

    return () => unsubscribe();
  }, []);

  if (!user && allowed === false) {
    return <Navigate to="/signin" replace />;
  }

  if (allowed === null) {
    return <p>Checking farmer approval...</p>;
  }

  return allowed ? children : <Navigate to="/dashboard" replace />;
}

function AdminRoute({ children }) {
  const [user, setUser] = React.useState(auth.currentUser);
  const [allowed, setAllowed] = React.useState(null);

  React.useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);

      if (!currentUser) {
        setAllowed(false);
        return;
      }

      const ok = await isAdmin(currentUser.uid);
      setAllowed(ok);
    });

    return () => unsubscribe();
  }, []);

  if (!user && allowed === false) {
    return <Navigate to="/signin" replace />;
  }

  if (allowed === null) {
    return <p>Checking admin...</p>;
  }

  return allowed ? children : <Navigate to="/" replace />;
}

function App() {
  return (
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/signin" element={<SignIn />} />
      <Route path="/register" element={<Register />} />

      <Route
        path="/dashboard"
        element={
          <ProtectedRoute>
            <ConsumerDashboard />
          </ProtectedRoute>
        }
      />

      <Route
        path="/farmerdashboard"
        element={
          <FarmerRoute>
            <FarmerDashboard />
          </FarmerRoute>
        }
      />

      <Route
        path="/prices"
        element={
          <ProtectedRoute>
            <Prices />
          </ProtectedRoute>
        }
      />

      <Route
        path="/profile"
        element={
          <ProtectedRoute>
            <Profile />
          </ProtectedRoute>
        }
      />

      <Route
        path="/admin"
        element={
          <AdminRoute>
            <Admin />
          </AdminRoute>
        }
      />

      <Route path="*" element={<Navigate to="/" />} />
    </Routes>
  );
}

export default App;
