import React, { useEffect, useState } from "react";
import { signOut } from "firebase/auth";
import { doc, getDoc, updateDoc } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import { auth, db } from "./firebaseConfig";
import { uploadToCloudinary } from "./cloudinairyUpload";
import "./Profile.css";

function formatValue(value) {
  if (value === null || value === undefined || value === "") {
    return "Not provided";
  }

  if (typeof value?.toDate === "function") {
    return value.toDate().toLocaleString();
  }

  if (Array.isArray(value)) {
    return value.length ? value.join(", ") : "Not provided";
  }

  if (typeof value === "object") {
    return null;
  }

  return String(value);
}

function InfoSection({ title, data }) {
  if (!data || typeof data !== "object") return null;

  const entries = Object.entries(data);

  if (!entries.length) return null;

  return (
    <section className="profile-section">
      <h2>{title}</h2>

      <div className="profile-fields">
        {entries.map(([key, value]) => {
          const formatted = formatValue(value);

          if (formatted === null) {
            return (
              <InfoSection
                key={key}
                title={key.replace(/([A-Z])/g, " $1")}
                data={value}
              />
            );
          }

          return (
            <div className="profile-field" key={key}>
              <span>{key.replace(/([A-Z])/g, " $1")}</span>
              <strong>{formatted}</strong>
            </div>
          );
        })}
      </div>
    </section>
  );
}

export default function Profile() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    const loadProfile = async () => {
      const user = auth.currentUser;

      if (!user) {
        navigate("/signin", { replace: true });
        return;
      }

      const snapshot = await getDoc(doc(db, "users", user.uid));

      if (snapshot.exists()) {
        setProfile({ id: snapshot.id, ...snapshot.data() });
      } else {
        setProfile({
          uid: user.uid,
          personalInfo: {
            email: user.email,
          },
        });
      }

      setLoading(false);
    };

    loadProfile();
  }, [navigate]);

  const uploadProfilePicture = async (event) => {
    const file = event.target.files?.[0];

    if (!file || !auth.currentUser) return;

    setUploading(true);

    try {
      const result = await uploadToCloudinary(
        file,
        `afriagrifed/users/${auth.currentUser.uid}/profile`
      );

      await updateDoc(doc(db, "users", auth.currentUser.uid), {
        profilePicture: {
          url: result.secure_url,
          publicId: result.public_id,
        },
      });

      setProfile((prev) => ({
        ...prev,
        profilePicture: {
          url: result.secure_url,
          publicId: result.public_id,
        },
      }));
    } catch (error) {
      console.error(error);
      alert("Profile picture upload failed: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const logout = async () => {
    await signOut(auth);
    navigate("/");
  };

  if (loading) {
    return <div className="profile-page">Loading profile...</div>;
  }

  const name = [
    profile?.personalInfo?.firstName,
    profile?.personalInfo?.lastName,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className="profile-page">
      <header className="profile-header">
        <div className="profile-identity">
          <img
            src={profile?.profilePicture?.url || "/logo192.png"}
            alt="Profile"
            className="profile-photo"
          />

          <div>
            <p className="eyebrow">My profile</p>
            <h1>{name || profile?.personalInfo?.email || "User Profile"}</h1>
            <p>{profile?.userType || "Account"} account</p>
          </div>
        </div>

        <div className="profile-actions">
          <label className="upload-btn">
            {uploading ? "Uploading..." : "Upload Photo"}
            <input
              type="file"
              accept="image/*"
              onChange={uploadProfilePicture}
              disabled={uploading}
            />
          </label>
          <button onClick={() => navigate(-1)}>Back</button>
          <button className="logout-btn" onClick={logout}>
            Logout
          </button>
        </div>
      </header>

      <main className="profile-content">
        <InfoSection title="Personal Information" data={profile.personalInfo} />
        <InfoSection title="Account Status" data={profile.accountStatus} />
        <InfoSection title="Questionnaire Information" data={profile.questionnaireData} />
        <InfoSection title="Documents" data={profile.documents} />
      </main>
    </div>
  );
}
