import React, {
  useState,
  useEffect
} from "react";

import {
  collection,
  onSnapshot
} from "firebase/firestore";

import {
  ref,
  push,
  onValue,
  set
} from "firebase/database";

import { signOut } from "firebase/auth";
import { useNavigate } from "react-router-dom";

import {
  db,
  auth,
  database
} from "./firebaseConfig";
import { uploadToCloudinary }
from "./cloudinairyUpload";

import "./ConsumerDashboard.css";





export default function ConsumerDashboard({ dashboardTitle = "Consumer Dashboard" }) {

  const [selectedPage, setSelectedPage] = useState("feed");
  const navigate = useNavigate();

  const [posts, setPosts] = useState([]);
  const [prices, setPrices] = useState([]);

  const [postText, setPostText] = useState("");

  const [commentText, setCommentText] = useState({});
  const [selectedImage, setSelectedImage] = useState(null);
  

  /*
  ==================================
  REAL TIME POSTS
  ==================================
  */

useEffect(() => {
  const postsRef = ref(database, "posts");

  const unsubscribe = onValue(postsRef, (snapshot) => {
    const data = snapshot.val();

    if (!data) {
      setPosts([]);
      return;
    }

    const postsArray = Object.entries(data).map(
      ([id, post]) => ({
        id,
        ...post
      })
    );

    postsArray.sort(
      (a, b) => b.createdAt - a.createdAt
    );

    setPosts(postsArray);
  });

  return () => unsubscribe();
}, []);

  /*
  ==================================
  REAL TIME PRICES
  ==================================
  */

  useEffect(() => {

    const unsubscribe = onSnapshot(
      collection(db, "marketPrices"),
      (snapshot) => {

        const data = snapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));

        setPrices(data);
      }
    );

    return () => unsubscribe();

  }, []);

  /*
  ==================================
  CREATE POST
  ==================================
  */
const createPost = async () => {

  if (!postText && !selectedImage)
    return;

  try {

    let imageUrl = "";

    if (selectedImage) {

      const result =
        await uploadToCloudinary(
          selectedImage,
          "posts"
        );

      imageUrl = result.secure_url;
    }

    await push(
      ref(database, "posts"),
      {
        userId: auth.currentUser.uid,
        userName: auth.currentUser.email,
        content: postText,
        imageUrl,
        comments: {},
        createdAt: Date.now()
      }
    );

    setPostText("");
    setSelectedImage(null);

  } catch (error) {

    console.error(error);

    alert(
      "Failed to upload post: " +
      error.message
    );
  }
};
  /*
  ==================================
  ADD COMMENT
  ==================================
  */
const addComment = async (postId) => {
  if (!commentText[postId]) return;

  const commentsRef = ref(
    database,
    `posts/${postId}/comments`
  );

  const newCommentRef = push(commentsRef);

  await set(newCommentRef, {
    userId: auth.currentUser.uid,
    text: commentText[postId],
    createdAt: Date.now()
  });

  setCommentText(prev => ({
    ...prev,
    [postId]: ""
  }));
};
  

  /*
  ==================================
  LOGOUT
  ==================================
  */

  const logout = async () => {

    await signOut(auth);

    window.location.href = "/";
  };

  const changePage = (page) => {
    setSelectedPage(page);

    if (page === "prices") {
      navigate("/prices");
    }

    if (page === "profile") {
      navigate("/profile");
    }
  };

  return (
    <div className="dashboard">

      {/* HEADER */}

      <header className="dashboard-header">

        <h1>{dashboardTitle}</h1>

        <div className="header-controls">

          <select
            value={selectedPage}
            onChange={(e) => changePage(e.target.value)}
          >

            <option value="feed">
              Community Feed
            </option>

            <option value="prices">
              Market Prices
            </option>

            <option value="profile">
              Profile
            </option>

          </select>

          <button
            className="logout-btn"
            onClick={logout}
          >
            Logout
          </button>

        </div>

      </header>

      {/* CREATE POST */}

      <div className="create-post">

        <h2>Create Post</h2>

        <textarea
          placeholder="Share something..."
          value={postText}
          onChange={(e) =>
            setPostText(e.target.value)
          }
        />
        <input
            type="file"
            accept="image/*"
        onChange={(e) =>
         setSelectedImage(e.target.files[0])
            }
        />

        <button onClick={createPost}>
          Post
        </button>

      </div>

      {/* MARKET PRICES */}

      {selectedPage === "prices" && (

        <div className="market-prices">

          <h2>Market Prices</h2>

          {prices.map(price => (

            <div
              key={price.id}
              className="price-card"
            >

              <h3>{price.product}</h3>

              <p>
                N${price.price}
              </p>

            </div>

          ))}

        </div>
      )}

      {/* POSTS */}

      {selectedPage === "feed" && (

        <div className="posts-section">

          <h2>Community Feed</h2>

          {posts.map(post => (

           <div
  key={post.id}
  className="post-card"
>
<h4>{post.userName}</h4>
  <p>{post.content}</p>

  {/* DISPLAY IMAGE */}

  {post.imageUrl && (
    <img
      src={post.imageUrl}
      alt="Post"
      className="post-image"
    />
  )}

  {/* COMMENTS */}

  <div className="comments">

    <h4>Comments</h4>

   {post.comments &&
  Object.values(post.comments).map(
    (comment, index) => (
     <div
  key={index}
  className="comment"
>
  <strong>{comment.userId}</strong>
  <p>{comment.text}</p>
</div>
    )
)}
    <input
      type="text"
      placeholder="Write a comment..."
      value={commentText[post.id] || ""}
      onChange={(e) =>
        setCommentText(prev => ({
          ...prev,
          [post.id]: e.target.value
        }))
      }
    />

    <button
      onClick={() =>
        addComment(post.id)
      }
    >
      Comment
    </button>

  </div>

</div>

          ))}

        </div>
      )}

    </div>
  );

}
